"bu uyarıdaki iddialara ilişkin görüşünüzü, tebliğ tarihinden itibaren {0} gün içinde, en geç {1} tarihine kadar yazılı olarak bildirmeniz ve elinizdeki delilleri eklemeniz gerekir. Bu süre içinde görüş bildirmezseniz, uyarıdaki iddiaları kabul etmiş sayılırsınız ({2} f. 5 ve 6). Tebliğden itibaren {3} gün içinde ({4} tarihine kadar) görüşünüzü sözlü olarak bildirmeyi talep etme hakkına sahipsiniz — bu durumda duruşma, uyarının tebliğinden itibaren 15 gün içinde, üyesi olduğunuz sendikanın temsilcisi ve talep etmeniz halinde kendi seçeceğiniz bir savunmacı huzurunda yapılır ve tutanak tutulur ({5} f. 7–12).",
