"Bu Yönetmelik ile İşverenin çalışanlarının yıllık izin süresi, artırım ölçütleri, kullanım biçimi ve usulü, izin planı, izin süresince ücret tazminatı ile ücretli ve ücretsiz izinleri düzenlenir. Genel Toplu İş Sözleşmesi 30.04.2026 tarihinden itibaren yürürlükte olmadığından, onun belirlediği haklar bu Yönetmelik ve iş sözleşmesiyle düzenlenir ({0}).",
"Bu Yönetmelik ile çalışanların iş yükümlülükleri, hafif ve ağır iş yükümlülüğü ihlalleri, bunlar için uygulanan tedbirler, sorumluluğun belirlenmesi usulü, işten geçici uzaklaştırma ve maddi sorumluluk belirlenir. Çalışan, yalnızca işlendiği sırada kanun, toplu iş sözleşmesi veya iş sözleşmesiyle tanımlanmış bir ihlalden sorumludur (md. 144 f. 4 ZOR); bu nedenle bu Yönetmelikteki ihlal listesi her çalışanın iş sözleşmesine de eklenir.",
