"Çalışan, {0} çalışma süresi ve standart verim için aylık brüt {1} tutarında temel maaşa hak kazanır; bu tutar, pozisyonun nitelik düzeyi için asgari ücretten düşük olamaz ({3}: V. düzeye kadar olan pozisyonlar için {4} EUR net, VI. ve daha yüksek düzey için {5} EUR net){6}. Çalışan ayrıca kanuna ve İşverenin genel işlemine uygun olarak maaşın özel kısmına (sıcak yemek ödeneği ve yıllık izin ödeneğinin 1/12'si) da hak kazanır.",
